import type { ImportedContentSourceFile } from '../librarySources';

export const elemental_evil_players_companion_source: ImportedContentSourceFile = JSON.parse("{\"schemaVersion\":\"ddbcc-v1\",\"sourceId\":\"elemental-evil\",\"label\":\"Elemental Evil Player's Companion\",\"category\":\"supplement\",\"aliases\":[],\"description\":\"Imported from 5etools data (source EEPC).\",\"content\":{\"species\":[{\"id\":\"elemental-evil-aarakocra\",\"name\":\"Aarakocra\",\"description\":\"Sequestered in high mountains atop tall trees, the aarakocra, sometimes called birdfolk, evoke fear and wonder. Many aarakocra aren't even native to the Material Plane. They hail from a world beyond-from the boundless vistas of the Elemental Plane of Air.\",\"size\":\"Medium\",\"speed\":25,\"abilityScoreIncreases\":[{\"ability\":\"dexterity\",\"amount\":2},{\"ability\":\"wisdom\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-aarakocra-age-0\",\"name\":\"Age\",\"description\":\"Aarakocra reach maturity by age 3. Compared to humans, aarakocra don't usually live longer than 30 years.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-aarakocra-alignment-1\",\"name\":\"Alignment\",\"description\":\"Most aarakocra are good and rarely choose sides when it comes to law and chaos. Tribal leaders and warriors might be lawful, while explorers and adventurers might tend toward chaotic.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-aarakocra-size-2\",\"name\":\"Size\",\"description\":\"Aarakocra are about 5 feet tall. They have thin, lightweight bodies that weigh between 80 and 100 pounds. Your size is Medium.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-aarakocra-flight-3\",\"name\":\"Flight\",\"description\":\"You have a flying speed of 50 feet. To use this speed, you can't be wearing medium or heavy armor.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-aarakocra-talons-4\",\"name\":\"Talons\",\"description\":\"Your talons are natural weapons, which you can use to make unarmed strikes. If you hit with them, you deal slashing damage equal to 1d4 + your Strength modifier, instead of the bludgeoning damage normal for an unarmed strike.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-aarakocra-language-5\",\"name\":\"Language\",\"description\":\"You can speak, read, and write Common, Aarakocra, and Auran.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"languages\":[\"Common\",\"Other\",\"Auran\"],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-genasi\",\"name\":\"Genasi\",\"description\":\"Genasi. Those who think of other planes at all consider them remote, distant realms, but planar influence can be felt throughout the world. It sometimes manifests in beings who, through an accident of birth, carry the power of the planes in their blood.\",\"size\":\"Medium\",\"speed\":30,\"abilityScoreIncreases\":[{\"ability\":\"constitution\",\"amount\":2}],\"features\":[{\"id\":\"elemental-evil-genasi-age-0\",\"name\":\"Age\",\"description\":\"Genasi mature at about the same rate as humans and reach adulthood in their late teens. They live somewhat longer than humans do, up to 120 years.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-genasi-alignment-1\",\"name\":\"Alignment\",\"description\":\"Independent and self-reliant, genasi tend toward a neutral alignment.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-genasi-size-2\",\"name\":\"Size\",\"description\":\"Genasi are as varied as their mortal parents but are generally built like humans, standing anywhere from 5 feet to over 6 feet tall. Your size is Medium.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-genasi-languages-3\",\"name\":\"Languages\",\"description\":\"You can speak, read, and write Common and Primordial. Primordial is a guttural language, filled with harsh syllables and hard consonants.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"languages\":[\"Common\",\"Primordial\"],\"variants\":[{\"id\":\"elemental-evil-genasi-air\",\"name\":\"Genasi (Air)\",\"description\":\"Unending Breath. You can hold your breath indefinitely while you're not incapacitated. Mingle with the Wind. You can cast the levitate spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell.\",\"abilityScoreIncreases\":[{\"ability\":\"dexterity\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-air-unending-breath-0\",\"name\":\"Unending Breath\",\"description\":\"You can hold your breath indefinitely while you're not incapacitated.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-air-mingle-with-the-wind-1\",\"name\":\"Mingle with the Wind\",\"description\":\"You can cast the levitate spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"spells\":[{\"name\":\"Levitate\",\"level\":2}]},{\"id\":\"elemental-evil-genasi-earth\",\"name\":\"Genasi (Earth)\",\"description\":\"Earth Walk. You can move across 3 made of earth or stone without expending extra movement. Merge with Stone. You can cast the pass without trace spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell.\",\"abilityScoreIncreases\":[{\"ability\":\"strength\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-earth-earth-walk-0\",\"name\":\"Earth Walk\",\"description\":\"You can move across 3 made of earth or stone without expending extra movement.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-earth-merge-with-stone-1\",\"name\":\"Merge with Stone\",\"description\":\"You can cast the pass without trace spell once with this trait, requiring no material components, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for this spell.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"spells\":[{\"name\":\"Pass Without Trace\",\"level\":2}]},{\"id\":\"elemental-evil-genasi-fire\",\"name\":\"Genasi (Fire)\",\"description\":\"Darkvision. You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. Your ties to the Elemental Plane of Fire make your darkvision unusual: everything you see in darkness is in a shade of red. Fire Resistance. You have resistance to fire damage. Reach to the Blaze. You know the produce flame cantrip. Once you reach 3rd level, you can cast the burning hands spell once with this trait as a 1st-level spell, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells.\",\"abilityScoreIncreases\":[{\"ability\":\"intelligence\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-fire-darkvision-0\",\"name\":\"Darkvision\",\"description\":\"You can see in dim light within 60 feet of you as if it were bright light, and in darkness as if it were dim light. Your ties to the Elemental Plane of Fire make your darkvision unusual: everything you see in darkness is in a shade of red.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-fire-fire-resistance-1\",\"name\":\"Fire Resistance\",\"description\":\"You have resistance to fire damage.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-fire-reach-to-the-blaze-2\",\"name\":\"Reach to the Blaze\",\"description\":\"You know the produce flame cantrip. Once you reach 3rd level, you can cast the burning hands spell once with this trait as a 1st-level spell, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"spells\":[{\"name\":\"Burning Hands\",\"level\":1,\"oncePerLongRest\":true},{\"name\":\"Produce Flame\",\"level\":0}]},{\"id\":\"elemental-evil-genasi-water\",\"name\":\"Genasi (Water)\",\"description\":\"Acid Resistance. You have resistance to acid damage. Amphibious. You can breathe air and water. Swim. You have a swimming speed of 30 feet. Call to the Wave. You know the shape water cantrip. When you reach 3rd level, you can cast the create or destroy water spell as a 2nd-level spell once with this trait, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells.\",\"abilityScoreIncreases\":[{\"ability\":\"wisdom\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-water-acid-resistance-0\",\"name\":\"Acid Resistance\",\"description\":\"You have resistance to acid damage.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-water-amphibious-1\",\"name\":\"Amphibious\",\"description\":\"You can breathe air and water.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-water-swim-2\",\"name\":\"Swim\",\"description\":\"You have a swimming speed of 30 feet.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-water-call-to-the-wave-3\",\"name\":\"Call to the Wave\",\"description\":\"You know the shape water cantrip. When you reach 3rd level, you can cast the create or destroy water spell as a 2nd-level spell once with this trait, and you regain the ability to cast it this way when you finish a long rest. Constitution is your spellcasting ability for these spells.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"spells\":[{\"name\":\"Create Or Destroy Water\",\"level\":2,\"oncePerLongRest\":true},{\"name\":\"Shape Water\",\"level\":0}]}],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-goliath\",\"name\":\"Goliath\",\"description\":\"At the highest mountain peaks-far above the slopes where trees grow and where the air is thin and the frigid winds howl-dwell the reclusive goliaths. Few folk can claim to have seen a goliath, and fewer still can claim friendship with them. Goliaths wander a bleak realm of rock, wind, and cold.\",\"size\":\"Medium\",\"speed\":30,\"abilityScoreIncreases\":[{\"ability\":\"strength\",\"amount\":2},{\"ability\":\"constitution\",\"amount\":1}],\"features\":[{\"id\":\"elemental-evil-goliath-age-0\",\"name\":\"Age\",\"description\":\"Goliaths have lifespans comparable to humans. They enter adulthood in their late teens and usually live less than a century.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-size-1\",\"name\":\"Size\",\"description\":\"Goliaths are between 7 and 8 feet tall and weigh between 280 and 340 pounds. Your size is Medium.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-natural-athlete-2\",\"name\":\"Natural Athlete\",\"description\":\"You have proficiency in the Athletics skill.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-stone-s-endurance-3\",\"name\":\"Stone's Endurance\",\"description\":\"You can focus yourself to occasionally shrug off injury. When you take damage, you can use your reaction to roll a d12. Add your Constitution modifier to the number rolled, and reduce the damage by that total. After you use this trait, you can't use it again until you finish a short or long rest.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-powerful-build-4\",\"name\":\"Powerful Build\",\"description\":\"You count as one size larger when determining your carrying capacity and the weight you can push, drag, or lift.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-mountain-born-5\",\"name\":\"Mountain Born\",\"description\":\"You have resistance to cold damage. You're also acclimated to high altitude, including elevations above 20,000 feet.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-goliath-languages-6\",\"name\":\"Languages\",\"description\":\"You can speak, read, and write Common and Giant.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"proficiencies\":[{\"name\":\"Athletics\",\"type\":\"skill\"}],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin\",\"name\":\"Gnome (Deep/Svirfneblin)\",\"description\":\"Forest gnomes and rock gnomes are the gnomes most commonly encountered in the lands of the surface world. There is another subrace of gnomes rarely seen by any surface-dweller: deep gnomes, also known as svirfneblin. Guarded, and suspicious of outsiders, svirfneblin are cunning and taciturn, but can be just as kind-hearted, loyal, and compassionate as their surface cousins.\",\"size\":\"Small\",\"speed\":25,\"abilityScoreIncreases\":[{\"ability\":\"dexterity\",\"amount\":1},{\"ability\":\"intelligence\",\"amount\":2}],\"features\":[{\"id\":\"elemental-evil-gnome-deep-svirfneblin-age-0\",\"name\":\"Age\",\"description\":\"Deep gnomes are short-lived for gnomes. They mature at the same rate humans do and are considered full-grown adults by 25. They live 200 to 250 years, although hard toil and the dangers of the Underdark often claim them before their time.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-size-1\",\"name\":\"Size\",\"description\":\"A typical svirfneblin stands about 3 to 3½ feet tall and weighs 80 to 120 pounds. Your size is Small.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-superior-darkvision-2\",\"name\":\"Superior Darkvision\",\"description\":\"Accustomed to life underground, you have superior vision in dark and dim conditions. You can see in dim light within 120 feet of you as if it were bright light, and in darkness as if it were dim light. You can't discern color in darkness, only shades of gray.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-gnome-cunning-3\",\"name\":\"Gnome Cunning\",\"description\":\"You have advantage on all Intelligence, Wisdom, and Charisma saving throws against magic.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-languages-4\",\"name\":\"Languages\",\"description\":\"You can speak, read, and write Common, Gnomish, and Undercommon. The svirfneblin dialect is more guttural than surface Gnomish, and most svirfneblin know only a little bit of Common, but those who deal with outsiders (and that includes you as an adventurer) pick up enough Common to get by in other lands.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-alignment-5\",\"name\":\"Alignment\",\"description\":\"Svirfneblin believe that survival depends on avoiding entanglements with other creatures and not making enemies, so they favor neutral alignments. They rarely wish others ill, and they are unlikely to take risks on behalf of others.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"},{\"id\":\"elemental-evil-gnome-deep-svirfneblin-stone-camouflage-6\",\"name\":\"Stone Camouflage\",\"description\":\"You have advantage on Dexterity (Stealth) checks to hide in rocky terrain.\",\"level\":1,\"source\":\"Elemental Evil Player's Companion\"}],\"languages\":[\"Common\",\"Gnomish\",\"Undercommon\"],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"}],\"classes\":[],\"subclasses\":[],\"backgrounds\":[],\"spells\":[{\"id\":\"elemental-evil-abi-dalzim-s-horrid-wilting\",\"name\":\"Abi-Dalzim's Horrid Wilting\",\"level\":8,\"school\":\"Necromancy\",\"castingTime\":\"1 action\",\"range\":\"150 feet\",\"components\":[\"V\",\"S\",\"M (a bit of sponge)\"],\"duration\":\"instant\",\"description\":\"You draw the moisture from every creature in a 30-foot cube centered on a point you choose within range. Each creature in that area must make a Constitution saving throw. Constructs and undead aren't affected, and plants and water elementals make this saving throw with disadvantage. A creature takes 12d8 necrotic damage on a failed save, or half as much damage on a successful one. Nonmagical plants in the area that aren't creatures, such as trees and shrubs, wither and die instantly.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-absorb-elements\",\"name\":\"Absorb Elements\",\"level\":1,\"school\":\"Abjuration\",\"castingTime\":\"1 reaction\",\"range\":\"self\",\"components\":[\"S\"],\"duration\":\"1 round\",\"description\":\"The spell captures some of the incoming energy, lessening its effect on you and storing it for your next melee attack. You have resistance to the triggering damage type until the start of your next turn. Also, the first time you hit with a melee attack on your next turn, the target takes an extra 1d6 damage of the triggering type, and the spell ends.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the extra damage increases by 1d6 for each slot level above 1st.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-aganazzar-s-scorcher\",\"name\":\"Aganazzar's Scorcher\",\"level\":2,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"30 feet\",\"components\":[\"V\",\"S\",\"M (a red dragon's scale)\"],\"duration\":\"instant\",\"description\":\"A line of roaring flame 30 feet long and 5 feet wide emanates from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 3d8 fire damage on a failed save, or half as much damage on a successful one.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 3d8 for each slot level above 2nd.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-beast-bond\",\"name\":\"Beast Bond\",\"level\":1,\"school\":\"Divination\",\"castingTime\":\"1 action\",\"range\":\"touch\",\"components\":[\"V\",\"S\",\"M (a bit of fur wrapped in a cloth)\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"You establish a telepathic link with one beast you touch that is friendly to you or charmed by you. The spell fails if the beast's Intelligence score is 4 or higher. Until the spell ends, the link is active while you and the beast are within line of sight of each other. Through the link, the beast can understand your telepathic messages to it, and it can telepathically communicate simple emotions and concepts back to you. While the link is active, the beast gains advantage on attack rolls against any creature within 5 feet of you that you can see.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-bones-of-the-earth\",\"name\":\"Bones of the Earth\",\"level\":6,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"120 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"You cause up to six pillars of stone to burst from places on the ground that you can see within range. Each pillar is a cylinder that has a diameter of 5 feet and a height of up to 30 feet. The ground where a pillar appears must be wide enough for its diameter, and you can target the ground under a creature if that creature is Medium or smaller. Each pillar has AC 5 and 30 hit points. When reduced to 0 hit points, a pillar crumbles into rubble, which creates an area of 3 with a 10-foot radius that lasts until the rubble is cleared. Each 5-foot-diameter portion of the area requires at least 1 minute to clear by hand. If a pillar is created under a creature, that creature must succeed on a Dexterity saving throw or be lifted by the pillar. A creature can choose to fail the save. If a pillar is prevented from reaching its full height because of a ceiling or other obstacle, a creature on the pillar takes 6d6 bludgeoning damage and is restrained, pinched between the pillar and the obstacle. The restrained creature can use an action to make a Strength or Dexterity check (the creature's choice) against the spell's save DC. On a success, the creature is no longer restrained and must either move off the pillar or fall off it.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 7th level or higher, you can create two additional pillars for each slot level above 6th.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-catapult\",\"name\":\"Catapult\",\"level\":1,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"S\"],\"duration\":\"instant\",\"description\":\"Choose one object weighing 1 to 5 pounds within range that isn't being worn or carried. The object flies in a straight line up to 90 feet in a direction you choose before falling to the ground, stopping early if it impacts against a solid surface. If the object would strike a creature, that creature must make a Dexterity saving throw. On a failed save, the object strikes the target and stops moving. When the object strikes something, the object and what it strikes each take 3d8 bludgeoning damage.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the maximum weight of objects that you can target with this spell increases by 5 pounds, and the damage increases by 3d8, for each slot level above 1st.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-control-flames\",\"name\":\"Control Flames\",\"level\":0,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"S\"],\"duration\":\"instant\",\"description\":\"You choose nonmagical flame that you can see within range and that fits within a 5-foot cube. You affect it in one of the following ways: You instantaneously expand the flame 5 feet in one direction, provided that wood or other fuel is present in the new location. You instantaneously extinguish the flames within the cube. You double or halve the area of bright light and dim light cast by the flame, change its color, or both. The change lasts for 1 hour. You cause simple shapes—such as the vague form of a creature, an inanimate object, or a location—to appear within the flames and animate as you like. The shapes last for 1 hour. If you cast this spell multiple times, you can have up to three non-instantaneous effects created by it active at a time, and you can dismiss such an effect as an action.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-control-winds\",\"name\":\"Control Winds\",\"level\":5,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"300 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 hour\",\"description\":\"You take control of the air in a 100-foot cube that you can see within range. Choose one of the following effects when you cast the spell. The effect lasts for the spell's duration, unless you use your action on a later turn to switch to a different effect. You can also use your action to temporarily halt the effect or to restart one you've halted. Gusts. A wind picks up within the cube, continually blowing in a horizontal direction you designate. You choose the intensity of the wind: calm, moderate, or strong. If the wind is moderate or strong, ranged weapon attacks that pass through it or that are made against targets within the cube have disadvantage on their attack rolls. If the wind is strong, any creature moving against the wind must spend 1 extra foot of movement for each foot moved. Downdraft. You cause a sustained blast of strong wind to blow downward from the top of the cube. Ranged weapon attacks that pass through the cube or that are made against targets within it have disadvantage on their attack rolls. A creature must make a Strength saving throw if it flies into the cube for the first time on a turn or starts its turn there flying. On a failed save, the creature is knocked prone. Updraft. You cause a sustained updraft within the cube, rising upward from the cube's bottom side. Creatures that end a fall within the cube take only half damage from the fall. When a creature in the cube makes a vertical jump, the creature can jump up to 10 feet higher than normal.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-create-bonfire\",\"name\":\"Create Bonfire\",\"level\":0,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"You create a bonfire on ground that you can see within range. Until the spell ends, the magic bonfire fills a 5-foot cube. Any creature in the bonfire's space when you cast the spell must succeed on a Dexterity saving throw or take 1d8 fire damage. A creature must also make the saving throw when it moves into the bonfire's space for the first time on a turn or ends its turn there. The bonfire ignites flammable objects in its area that aren't being worn or carried. The spell's damage increases by 1d8 when you reach 5th level (2d8), 11th level (3d8), and 17th level (4d8).\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-dust-devil\",\"name\":\"Dust Devil\",\"level\":2,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\",\"M (a pinch of dust)\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"Choose an unoccupied 5-foot cube of air that you can see within range. An elemental force that resembles a dust devil appears in the cube and lasts for the spell's duration. Any creature that ends its turn within 5 feet of the dust devil must make a Strength saving throw. On a failed save, the creature takes 1d8 bludgeoning damage and is pushed 10 feet away from the dust devil. On a successful save, the creature takes half as much damage and isn't pushed. As a bonus action, you can move the dust devil up to 30 feet in any direction. If the dust devil moves over sand, dust, loose dirt, or light gravel, it sucks up the material and forms a 10-foot-radius cloud of debris around itself that lasts until the start of your next turn. The cloud heavily obscures its area.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 1d8 for each slot level above 2nd.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-earth-tremor\",\"name\":\"Earth Tremor\",\"level\":1,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"10 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"You cause a tremor in the ground within range. Each creature other than you in that area must make a Dexterity saving throw. On a failed save, a creature takes 1d6 bludgeoning damage and is knocked prone. If the ground in that area is loose earth or stone, it becomes 3 until cleared, with each 5-foot-diameter portion requiring at least 1 minute to clear by hand.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the damage increases by 1d6 for each slot level above 1st.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-earthbind\",\"name\":\"Earthbind\",\"level\":2,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"300 feet\",\"components\":[\"V\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"Choose one creature you can see within range. Yellow strips of magical energy loop around the creature. The target must succeed on a Strength saving throw, or its flying speed (if any) is reduced to 0 feet for the spell's duration. An airborne creature affected by this spell safely descends at 60 feet per round until it reaches the ground or the spell ends.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-elemental-bane\",\"name\":\"Elemental Bane\",\"level\":4,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"Choose one creature you can see within range, and choose one of the following damage types: acid, cold, fire, lightning, or thunder. The target must succeed on a Constitution saving throw or be affected by the spell for its duration. The first time each turn the affected target takes damage of the chosen type, the target takes an extra 2d6 damage of that type. Moreover, the target loses any resistance to that damage type until the spell ends.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, you can target one additional creature for each slot level above 4th. The creatures must be within 30 feet of each other when you target them.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-erupting-earth\",\"name\":\"Erupting Earth\",\"level\":3,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"120 feet\",\"components\":[\"V\",\"S\",\"M (a piece of obsidian)\"],\"duration\":\"instant\",\"description\":\"Choose a point you can see on the ground within range. A fountain of churned earth and stone erupts in a 20-foot cube centered on that point. Each creature in that area must make a Dexterity saving throw. A creature takes 3d12 bludgeoning damage on a failed save, or half as much damage on a successful one. Additionally, the ground in that area becomes 3 until cleared. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the damage increases by 3d12 for each slot level above 3rd.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-flame-arrows\",\"name\":\"Flame Arrows\",\"level\":3,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"touch\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 hour\",\"description\":\"You touch a quiver containing arrows or bolts. When a target is hit by a ranged weapon attack using a piece of ammunition drawn from the quiver, the target takes an extra 1d6 fire damage. The spell's magic ends on a piece of ammunition when it hits or misses, and the spell ends when twelve pieces of ammunition have been drawn from the quiver.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of pieces of ammunition you can affect with this spell increases by two for each slot level above 3rd.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-frostbite\",\"name\":\"Frostbite\",\"level\":0,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"You cause numbing frost to form on one creature that you can see within range. The target must make a Constitution saving throw. On a failed save, the target takes 1d6 cold damage, and it has disadvantage on the next weapon attack roll it makes before the end of its next turn. The spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-gust\",\"name\":\"Gust\",\"level\":0,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"30 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"You seize the air and compel it to create one of the following effects at a point you can see within range: One Medium or smaller creature that you choose must succeed on a Strength saving throw or be pushed up to 5 feet away from you. You create a small blast of air capable of moving one object that is neither held nor carried and that weighs no more than 5 pounds. The object is pushed up to 10 feet away from you. It isn't pushed with enough force to cause damage. You create a harmless sensory effect using air, such as causing leaves to rustle, wind to slam shutters closed, or your clothing to ripple in a breeze.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-ice-knife\",\"name\":\"Ice Knife\",\"level\":1,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"S\",\"M (a drop of water or piece of ice)\"],\"duration\":\"instant\",\"description\":\"You create a shard of ice and fling it at one creature within range. Make a ranged spell attack against the target. On a hit, the target takes 1d10 piercing damage. Hit or miss, the shard then explodes. The target and each creature within 5 feet of it must succeed on a Dexterity saving throw or take 2d6 cold damage.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 2nd level or higher, the cold damage increases by 2d6 for each slot level above 1st.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-immolation\",\"name\":\"Immolation\",\"level\":5,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"Flames wreathe one creature you can see within range. The target must make a Dexterity saving throw. It takes 8d6 fire damage on a failed save, or half as much damage on a successful one. On a failed save, the target also burns for the spell's duration. The burning target sheds bright light in a 30-foot radius and dim light for an additional 30 feet. At the end of each of its turns, the target repeats the saving throw. It takes 4d6 fire damage on a failed save, and the spell ends on a successful one. These magical flames can't be extinguished by nonmagical means. If damage from this spell kills a target, the target is turned to ash.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-investiture-of-flame\",\"name\":\"Investiture of Flame\",\"level\":6,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"Flames race across your body, shedding bright light in a 30-foot radius and dim light for an additional 30 feet for the spell's duration. The flames don't harm you. Until the spell ends, you gain the following benefits: You are immune to fire damage and have resistance to cold damage. Any creature that moves within 5 feet of you for the first time on a turn or ends its turn there takes 1d10 fire damage. You can use your action to create a line of fire 15 feet long and 5 feet wide extending from you in a direction you choose. Each creature in the line must make a Dexterity saving throw. A creature takes 4d8 fire damage on a failed save, or half as much damage on a successful one.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-investiture-of-ice\",\"name\":\"Investiture of Ice\",\"level\":6,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"Until the spell ends, ice rimes your body, and you gain the following benefits: You are immune to cold damage and have resistance to fire damage. You can move across 3 created by ice or snow without spending extra movement. The ground in a 10-foot radius around you is icy and is 3 for creatures other than you. The radius moves with you. You can use your action to create a 15-foot cone of freezing wind extending from your outstretched hand in a direction you choose. Each creature in the cone must make a Constitution saving throw. A creature takes 4d6 cold damage on a failed save, or half as much damage on a successful one. A creature that fails its save against this effect has its speed halved until the start of your next turn.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-investiture-of-stone\",\"name\":\"Investiture of Stone\",\"level\":6,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"Until the spell ends, bits of rock spread across your body, and you gain the following benefits: You have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks. You can use your action to create a small earthquake on the ground in a 15-foot radius centered on you. Other creatures on that ground must succeed on a Dexterity saving throw or be knocked prone. You can move across 3 made of earth or stone without spending extra movement. You can move through solid earth or stone as if it was air and without destabilizing it, but you can't end your movement there. If you do so, you are ejected to the nearest unoccupied space, this spell ends, and you are stunned until the end of your next turn.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-investiture-of-wind\",\"name\":\"Investiture of Wind\",\"level\":6,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"Until the spell ends, wind whirls around you, and you gain the following benefits: Ranged weapon attacks made against you have disadvantage on the attack roll. You gain a flying speed of 60 feet. If you are still flying when the spell ends, you fall, unless you can somehow prevent it. You can use your action to create a 15-foot cube of swirling wind centered on a point you can see within 60 feet of you. Each creature in that area must make a Constitution saving throw. A creature takes 2d10 bludgeoning damage on a failed save, or half as much damage on a successful one. If a Large or smaller creature fails the save, that creature is also pushed up to 10 feet away from the center of the cube.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-maelstrom\",\"name\":\"Maelstrom\",\"level\":5,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"120 feet\",\"components\":[\"V\",\"S\",\"M (paper or leaf in the shape of a funnel)\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"A swirling mass of 5-foot-deep water appears in a 30-foot radius centered on a point you can see within range. The point must be on the ground or in a body of water. Until the spell ends, that area is 3, and any creature that starts its turn there must succeed on a Strength saving throw or take 6d6 bludgeoning damage and be pulled 10 feet toward the center.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-magic-stone\",\"name\":\"Magic Stone\",\"level\":0,\"school\":\"Transmutation\",\"castingTime\":\"1 bonus\",\"range\":\"touch\",\"components\":[\"V\",\"S\"],\"duration\":\"1 minute\",\"description\":\"You touch one to three pebbles and imbue them with magic. You or someone else can make a ranged spell attack with one of the pebbles by throwing it or hurling it with a sling. If thrown, a pebble has a range of 60 feet. If someone else attacks with a pebble, that attacker adds your spellcasting ability modifier, not the attacker's, to the attack roll. On a hit, the target takes bludgeoning damage equal to 1d6 + your spellcasting ability modifier. Whether the attack hits or misses, the spell then ends on the stone. If you cast this spell again, the spell ends on any pebbles still affected by your previous casting.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-maximilian-s-earthen-grasp\",\"name\":\"Maximilian's Earthen Grasp\",\"level\":2,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"30 feet\",\"components\":[\"V\",\"S\",\"M (a miniature hand sculpted from clay)\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"You choose a 5-foot-square unoccupied space on the ground that you can see within range. A Medium hand made from compacted soil rises there and reaches for one creature you can see within 5 feet of it. The target must make a Strength saving throw. On a failed save, the target takes 2d6 bludgeoning damage and is restrained for the spell's duration. As an action, you can cause the hand to crush the restrained target, which must make a Strength saving throw. The target takes 2d6 bludgeoning damage on a failed save, or half as much damage on a successful one. To break out, the restrained target can use its action to make a Strength check against your spell save DC. On a success, the target escapes and is no longer restrained by the hand. As an action, you can cause the hand to reach for a different creature or to move to a different unoccupied space within range. The hand releases a restrained target if you do either.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-melf-s-minute-meteors\",\"name\":\"Melf's Minute Meteors\",\"level\":3,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\",\"M (niter, sulfur, and pine tar formed into a bead)\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"You create six tiny meteors in your space. They float in the air and orbit you for the spell's duration. When you cast the spell—and as a bonus action on each of your turns thereafter—you can expend one or two of the meteors, sending them streaking toward a point or points you choose within 120 feet of you. Once a meteor reaches its destination or impacts against a solid surface, the meteor explodes. Each creature within 5 feet of the point where the meteor explodes must make a Dexterity saving throw. A creature takes 2d6 fire damage on a failed save, or half as much damage on a successful one.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 4th level or higher, the number of meteors created increases by two for each slot level above 3rd.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-mold-earth\",\"name\":\"Mold Earth\",\"level\":0,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"30 feet\",\"components\":[\"S\"],\"duration\":\"instant\",\"description\":\"You choose a portion of dirt or stone that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways: If you target an area of loose earth, you can instantaneously excavate it, move it along the ground, and deposit it up to 5 feet away. This movement doesn't involve enough force to cause damage. You cause shapes, colors, or both to appear on the dirt or stone, spelling out words, creating images, or shaping patterns. The changes last for 1 hour. If the dirt or stone you target is on the ground, you cause it to become 3. Alternatively, you can cause the ground to become normal terrain if it is already 3. This change lasts for 1 hour. If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-primordial-ward\",\"name\":\"Primordial Ward\",\"level\":6,\"school\":\"Abjuration\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"You have resistance to acid, cold, fire, lightning, and thunder damage for the spell's duration. When you take damage of one of those types, you can use your reaction to gain immunity to that type of damage, including against the triggering damage. If you do so, the resistances end, and you have the immunity until the end of your next turn, at which time the spell ends.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-pyrotechnics\",\"name\":\"Pyrotechnics\",\"level\":2,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"Choose an area of nonmagical flame that you can see and that fits within a 5-foot cube within range. You can extinguish the fire in that area, and you create either fireworks or smoke when you do so. Fireworks. The target explodes with a dazzling display of colors. Each creature within 10 feet of the target must succeed on a Constitution saving throw or become blinded until the end of your next turn. Smoke. Thick black smoke spreads out from the target in a 20-foot radius, moving around corners. The area of the smoke is heavily obscured. The smoke persists for 1 minute or until a strong wind disperses it.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-shape-water\",\"name\":\"Shape Water\",\"level\":0,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"30 feet\",\"components\":[\"S\"],\"duration\":\"instant\",\"description\":\"You choose an area of water that you can see within range and that fits within a 5-foot cube. You manipulate it in one of the following ways: You instantaneously move or otherwise change the flow of the water as you direct, up to 5 feet in any direction. This movement doesn't have enough force to cause damage. You cause the water to form into simple shapes and animate at your direction. This change lasts for 1 hour. You change the water's color or opacity. The water must be changed in the same way throughout. This change lasts for 1 hour. You freeze the water, provided that there are no creatures in it. The water unfreezes in 1 hour. If you cast this spell multiple times, you can have no more than two of its non-instantaneous effects active at a time, and you can dismiss such an effect as an action.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-skywrite\",\"name\":\"Skywrite\",\"level\":2,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"sight\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 hour\",\"description\":\"You cause up to ten words to form in a part of the sky you can see. The words appear to be made of cloud and remain in place for the spell's duration. The words dissipate when the spell ends. A strong wind can disperse the clouds and end the spell early.\",\"ritual\":true,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-snilloc-s-snowball-swarm\",\"name\":\"Snilloc's Snowball Swarm\",\"level\":2,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\",\"S\",\"M (a piece of ice or a small white rock chip)\"],\"duration\":\"instant\",\"description\":\"A flurry of magic snowballs erupts from a point you choose within range. Each creature in a 5-foot-radius sphere centered on that point must make a Dexterity saving throw. A creature takes 3d6 cold damage on a failed save, or half as much damage on a successful one.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 3d6 for each slot level above 2nd.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-storm-sphere\",\"name\":\"Storm Sphere\",\"level\":4,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"150 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"A 20-foot-radius sphere of whirling air springs into existence, centered on a point you choose within range. The sphere remains for the spell's duration. Each creature in the sphere when it appears or that ends its turn there must succeed on a Strength saving throw or take 2d6 bludgeoning damage. The sphere's space is 3. Until the spell ends, you can use a bonus action on each of your turns to cause a bolt of lightning to leap from the center of the sphere toward one creature you choose within 60 feet of the center. Make a ranged spell attack. You have advantage on the attack roll if the target is in the sphere. On a hit, the target takes 4d6 lightning damage. Creatures within 30 feet of the sphere have disadvantage on Wisdom (Perception) checks made to listen.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the damage for each of its effects increases by 2d6;4d6 for each slot level above 4th.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-thunderclap\",\"name\":\"Thunderclap\",\"level\":0,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"5 feet\",\"components\":[\"S\"],\"duration\":\"instant\",\"description\":\"You create a burst of thunderous sound that can be heard up to 100 feet away. Each creature within range, other than you, must make a Constitution saving throw or take 1d6 thunder damage. The spell's damage increases by 1d6 when you reach 5th level (2d6), 11th level (3d6), and 17th level (4d6).\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-tidal-wave\",\"name\":\"Tidal Wave\",\"level\":3,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"120 feet\",\"components\":[\"V\",\"S\",\"M (a drop of water)\"],\"duration\":\"instant\",\"description\":\"You conjure up a wave of water that crashes down on an area within range. The area can be up to 30 feet long, up to 10 feet wide, and up to 10 feet tall. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes 4d8 bludgeoning damage and is knocked prone. On a successful save, a creature takes half as much damage and isn't knocked prone. The water then spreads out across the ground in all directions, extinguishing unprotected flames in its area and within 30 feet of it, and then it vanishes.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-transmute-rock\",\"name\":\"Transmute Rock\",\"level\":5,\"school\":\"Transmutation\",\"castingTime\":\"1 action\",\"range\":\"120 feet\",\"components\":[\"V\",\"S\",\"M (clay and water)\"],\"duration\":\"permanent\",\"description\":\"You choose an area of stone or mud that you can see that fits within a 40-foot cube and is within range, and choose one of the following effects. Transmute Rock to Mud. Nonmagical rock of any sort in the area becomes an equal volume of thick, flowing mud that remains for the spell's duration. The ground in the spell's area becomes muddy enough that creatures can sink into it. Each foot that a creature moves through the mud costs 4 feet of movement, and any creature on the ground when you cast the spell must make a Strength saving throw. A creature must also make the saving throw when it moves into the area for the first time on a turn or ends its turn there. On a failed save, a creature sinks into the mud and is restrained, though it can use an action to end the restrained condition on itself by pulling itself free of the mud. If you cast the spell on a ceiling, the mud falls. Any creature under the mud when it falls must make a Dexterity saving throw. A creature takes 4d8 bludgeoning damage on a failed save, or half as much damage on a successful one. Transmute Mud to Rock. Nonmagical mud or quicksand in the area no more than 10 feet deep transforms into soft stone for the spell's duration. Any creature in the mud when it transforms must make a Dexterity saving throw. On a successful save, a creature is shunted safely to the surface in an unoccupied space. On a failed save, a creature becomes restrained by the rock. A restrained creature, or another creature within reach, can use an action to try to break the rock by succeeding on a DC 20 Strength check or by dealing damage to it. The rock has AC 15 and 25 hit points, and it is immune to poison and psychic damage.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-vitriolic-sphere\",\"name\":\"Vitriolic Sphere\",\"level\":4,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"150 feet\",\"components\":[\"V\",\"S\",\"M (a drop of giant slug bile)\"],\"duration\":\"instant\",\"description\":\"You point at a location within range, and a glowing 1-foot-diameter ball of emerald acid streaks there and explodes in a 20-foot-radius sphere. Each creature in that area must make a Dexterity saving throw. On a failed save, a creature takes 10d4 acid damage and another 5d4 acid damage at the end of its next turn. On a successful save, a creature takes half the initial damage and no damage at the end of its next turn.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 5th level or higher, the initial damage increases by 10d4 for each slot level above 4th.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-wall-of-sand\",\"name\":\"Wall of Sand\",\"level\":3,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\",\"S\",\"M (a handful of sand)\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"You create a wall of swirling sand on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 10 feet thick, and it vanishes when the spell ends. It blocks line of sight but not movement. A creature is blinded while in the wall's space and must spend 3 feet of movement for every 1 foot it moves there.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-wall-of-water\",\"name\":\"Wall of Water\",\"level\":3,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\",\"M (a drop of water)\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"You create a wall of water on the ground at a point you can see within range. You can make the wall up to 30 feet long, 10 feet high, and 1 foot thick, or you can make a ringed wall up to 20 feet in diameter, 20 feet high, and 1 foot thick. The wall vanishes when the spell ends. The wall's space is 3. Any ranged weapon attack that enters the wall's space has disadvantage on the attack roll, and fire damage is halved if the fire effect passes through the wall to reach its target. Spells that deal cold damage that pass through the wall cause the area of the wall they pass through to freeze solid (at least a 5-foot-square section is frozen). Each 5-foot-square frozen section has AC 5 and 15 hit points. Reducing a frozen section to 0 hit points destroys it. When a section is destroyed, the wall's water doesn't fill it.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-warding-wind\",\"name\":\"Warding Wind\",\"level\":2,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\"],\"duration\":\"Concentration, up to 10 minute\",\"description\":\"A strong wind (20 miles per hour) blows around you in a 10-foot radius and moves with you, remaining centered on you. The wind lasts for the spell's duration. The wind has the following effects: It deafens you and other creatures in its area. It extinguishes unprotected flames in its area that are torch-sized or smaller. It hedges out vapor, gas, and fog that can be dispersed by strong wind. The area is 3 for creatures other than you. The attack rolls of ranged weapon attacks have disadvantage if the attacks pass in or out of the wind.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-watery-sphere\",\"name\":\"Watery Sphere\",\"level\":4,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\",\"S\",\"M (a droplet of water)\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"You conjure up a sphere of water with a 5-foot radius at a point you can see within range. The sphere can hover but no more than 10 feet off the ground. The sphere remains for the spell's duration. Any creature in the sphere's space must make a Strength saving throw. On a successful save, a creature is ejected from that space to the nearest unoccupied space of the creature's choice outside the sphere. A Huge or larger creature succeeds on the saving throw automatically, and a Large or smaller creature can choose to fail it. On a failed save, a creature is restrained by the sphere and is engulfed by the water. At the end of each of its turns, a restrained target can repeat the saving throw, ending the effect on itself on a success. The sphere can restrain as many as four Medium or smaller creatures or one Large creature. If the sphere restrains a creature that causes it to exceed this capacity, a random creature that was already restrained by the sphere falls out of it and lands prone in a space within 5 feet of it. As an action, you can move the sphere up to 30 feet in a straight line. If it moves over a pit, a cliff, or other drop-off, it safely descends until it is hovering 10 feet above the ground. Any creature restrained by the sphere moves with it. You can ram the sphere into creatures, forcing them to make the saving throw. When the spell ends, the sphere falls to the ground and extinguishes all normal flames within 30 feet of it. Any creature restrained by the sphere is knocked prone in the space where it falls. The water then vanishes.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"},{\"id\":\"elemental-evil-whirlwind\",\"name\":\"Whirlwind\",\"level\":7,\"school\":\"Evocation\",\"castingTime\":\"1 action\",\"range\":\"300 feet\",\"components\":[\"V\",\"M (a piece of straw)\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"A whirlwind howls down to a point that you can see on the ground within range. The whirlwind is a 10-foot-radius, 30-foot-high cylinder centered on that point. Until the spell ends, you can use your action to move the whirlwind up to 30 feet in any direction along the ground. The whirlwind sucks up any Medium or smaller objects that aren't secured to anything and that aren't worn or carried by anyone. A creature must make a Dexterity saving throw the first time on a turn that it enters the whirlwind or that the whirlwind enters its space, including when the whirlwind first appears. A creature takes 10d6 bludgeoning damage on a failed save, or half as much damage on a successful one. In addition, a Large or smaller creature that fails the save must succeed on a Strength saving throw or become restrained in the whirlwind until the spell ends. When a creature starts its turn restrained by the whirlwind, the creature is pulled 5 feet higher inside it, unless the creature is at the top. A restrained creature moves with the whirlwind and falls when the spell ends, unless the creature has some means to stay aloft. A restrained creature can use an action to make a Strength or Dexterity check against your spell save DC. If successful, the creature is no longer restrained by the whirlwind and is hurled 3d6 × 10 feet away from it in a random direction.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Elemental Evil Player's Companion\",\"sourceId\":\"elemental-evil\"}],\"equipment\":[],\"feats\":[],\"monsters\":[],\"ua\":[]},\"note\":\"Converted from 5etools JSON filtered to source \\\"EEPC\\\".\",\"notes\":[\"Converted from 5etools JSON filtered to source \\\"EEPC\\\".\",\"Includes entries this book reprints from another printing (5etools `otherSources`).\"],\"documents\":[],\"sections\":[],\"meta\":{\"origin\":\"imported-json\",\"importedAt\":\"2026-10-14T17:54:14.102Z\",\"parser\":\"5etools-adapter\",\"visibility\":\"private\"}}");

